//! The actual completed preprocessor queue lent to the SAME native Pratt.
//! Owned token/value/credit moves once; canonical chunks accompany the SAME projection without relex or replay.
use super::{original_output_queue::OriginalOutputQueue,original_conditional_pump::OriginalCompletedCondition,original_native_projection::{project_native_token_using,Adjacency,needs_separator}};
use crate::{SourceProvider,macro_expansion::{OriginalMacroRows as Rows,OriginalMacroToken as ActualToken}};
use dm_syntax::{SettingAdmission,SettingRootLease,Span,Token,NativeExpressionTokenDemand,NativeExpressionTokenOccurrence,OriginalLiteralData,OriginalTokenValue};
use std::{io,cell::Cell};
#[derive(Clone,Copy)]pub(super) enum DebugSupport{Complete,Unissued(&'static str)}
macro_rules! debug_step{($call:expr)=>{match $call?{DebugSupport::Complete=>(),unissued=>return Ok(unissued)}}}
struct Occurrence{actual:ActualToken<'static>,span:Span,literal:Option<OriginalLiteralData>,credit:Option<SettingRootLease>}
enum ParserEvent{Primitive{at:NativeExpressionTokenOccurrence,kind:dm_syntax::OriginalInputNoticeKind},MissingMember{separator:NativeExpressionTokenOccurrence,following:Option<NativeExpressionTokenOccurrence>}}
pub(super) struct OriginalConditionTokens<'a,'budget>{queue:&'a mut OriginalOutputQueue<'static>,provider:&'a dyn SourceProvider,a:&'a SettingAdmission<'budget>,rows:Rows<Occurrence>,events:Rows<ParserEvent>,source:crate::macro_expansion::OriginalMacroText,next_offset:usize,last:Option<Adjacency>,begun:bool,failed:Cell<bool>,completion:OriginalCompletedCondition}
impl<'a,'budget> OriginalConditionTokens<'a,'budget>{
 pub(super) fn new(queue:&'a mut OriginalOutputQueue<'static>,provider:&'a dyn SourceProvider,a:&'a SettingAdmission<'budget>,completion:OriginalCompletedCondition)->io::Result<Self>{Ok(Self{queue,provider,a,rows:Rows::new(a)?,events:Rows::new(a)?,source:crate::macro_expansion::OriginalMacroText::new(a)?,next_offset:0,last:None,begun:false,failed:Cell::new(false),completion})}
 pub(super) fn last_input(&self)->crate::macro_expansion::OriginalMacroOrigin{self.completion.last_input()}
 fn check(&self)->io::Result<()>{if self.failed.get(){return Err(io::ErrorKind::InvalidInput.into())}let result=self.a.checkpoint().map_err(|e|self.a.take_operational_error().unwrap_or(e));if result.is_err(){self.failed.set(true)}result}
 fn row(&self,occurrence:NativeExpressionTokenOccurrence)->io::Result<&Occurrence>{self.check()?;let row=self.rows.as_slice().get(occurrence.ordinal()).ok_or(io::ErrorKind::InvalidInput)?;if row.span!=occurrence.span(){return Err(io::ErrorKind::InvalidInput.into())}Ok(row)}
 /// Keep the SAME Pratt result alive while formatting its typed failure:
 /// that result owns the moved spelling credit; this row loans actual VALUE.
 pub(super) fn failure_using(&self,span:Option<Span>,input:Option<dm_syntax::OriginalInputExpected>,initial:crate::macro_expansion::OriginalMacroOrigin)->io::Result<(crate::macro_expansion::OriginalMacroText,crate::macro_expansion::OriginalMacroOrigin)>{self.check()?;let row=match span{Some(span)=>Some(self.rows.as_slice().iter().find(|row|row.span==span).ok_or(io::ErrorKind::InvalidInput)?),None=>None};let value=row.map(|row|row.actual.value.map_text(|text|text.get()));let place=row.or_else(||self.rows.as_slice().last()).map_or(initial,|row|row.actual.origin);let mut text=crate::macro_expansion::OriginalMacroText::new(self.a)?;crate::macro_expansion::original_format_using(&mut text,self.a,|out|match input{Some(expected)=>dm_syntax::write_original_input_failure(out,value,expected),None=>dm_syntax::write_original_term_failure(out,value)})?;Ok((text,place))}
 pub(super) fn observe_notices_using(&self,notices:&dm_syntax::OriginalInputNotices,sink:&mut dyn super::original_raw_inputs::OriginalRawNoticeSink)->io::Result<()>{self.check()?;if !notices.is_admitted_by(self.a){return Err(io::ErrorKind::InvalidInput.into())}let mut primitive=notices.as_slice().iter();for event in self.events.as_slice(){self.check()?;match event{ParserEvent::Primitive{at,kind}=>{let row=self.row(*at)?;let actual=primitive.next().ok_or(io::ErrorKind::InvalidData)?;if actual.span()!=at.span()||actual.kind()!=*kind{return Err(io::ErrorKind::InvalidData.into())}sink.condition_primitive(row.actual.origin,*kind,row.actual.value.map_text(|text|text.get()),self.a)?},ParserEvent::MissingMember{separator,following}=>{let separator=self.row(*separator)?;let following=following.map(|row|self.row(row)).transpose()?;let place=following.map_or(separator.actual.origin,|row|row.actual.origin);let value=following.map(|row|row.actual.value.map_text(|text|text.get()));sink.condition_identifier_recovery(place,value,self.a)?}}}if primitive.next().is_some(){return Err(io::ErrorKind::InvalidData.into())}Ok(())}
 pub(super) fn delimiter_failure_using(&self,expected:dm_syntax::NativeDelimiterExpectation,initial:crate::macro_expansion::OriginalMacroOrigin)->io::Result<(crate::macro_expansion::OriginalMacroText,crate::macro_expansion::OriginalMacroOrigin)>{self.check()?;let row=match expected.token_span(){Some(span)=>Some(self.rows.as_slice().iter().find(|row|row.span==span).ok_or(io::ErrorKind::InvalidInput)?),None=>None};let value=row.map(|row|row.actual.value.map_text(|text|text.get()));let place=row.or_else(||self.rows.as_slice().last()).map_or(initial,|row|row.actual.origin);let mut text=crate::macro_expansion::OriginalMacroText::new(self.a)?;crate::macro_expansion::original_format_using(&mut text,self.a,|out|dm_syntax::write_original_delimiter_failure(out,value,expected.expected()))?;Ok((text,place))}
 fn debug_row_at_start(&self,start:usize)->io::Result<&Occurrence>{self.check()?;for row in self.rows.as_slice(){self.check()?;if row.span.start==start{return Ok(row)}}Err(io::ErrorKind::InvalidData.into())}
 fn debug_location(&self,row:&Occurrence,out:&mut crate::macro_expansion::OriginalMacroText,file:&mut dyn FnMut(usize)->io::Result<u32>)->io::Result<()>{self.check()?;let id=file(row.actual.origin.occurrence)?;let column=row.actual.origin.byte_column.ok_or_else(||io::Error::new(io::ErrorKind::Unsupported,"actual Original Debug token has no raw column loan"))?;crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Location {{ file: FileId({id}), line: {}, column: {} }}",row.actual.origin.line,column)})}
 /// Borrow actual AST+typed token rows; no constant folding/relex/new AST.
 pub(super) fn write_expression_debug_using(&self,expr:&dm_syntax::Expr,out:&mut crate::macro_expansion::OriginalMacroText,file:&mut dyn FnMut(usize)->io::Result<u32>)->io::Result<DebugSupport>{
  self.check()?;let _frame=self.a.evaluation_frame().map_err(|error|self.a.take_operational_error().unwrap_or(error))?;
  match &expr.kind{
   dm_syntax::ExprKind::Binary{op,lhs,rhs}=>{let(op,assignment)=match op.as_str(){"+"=>("Add",false),"-"=>("Sub",false),"*"=>("Mul",false),"/"=>("Div",false),"**"=>("Pow",false),"%"=>("Mod",false),"%%"=>("FloatMod",false),"=="=>("Eq",false),"!="=>("NotEq",false),"<"=>("Less",false),">"=>("Greater",false),"<="=>("LessEq",false),">="=>("GreaterEq",false),"<=>"=>("LessOrGreater",false),"~="=>("Equiv",false),"~!"=>("NotEquiv",false),"&"=>("BitAnd",false),"^"=>("BitXor",false),"|"=>("BitOr",false),"<<"=>("LShift",false),">>"=>("RShift",false),"&&"=>("And",false),"||"=>("Or",false),"in"=>("In",false),"to"=>("To",false),"="=>("Assign",true),"+="=>("AddAssign",true),"-="=>("SubAssign",true),"*="=>("MulAssign",true),"/="=>("DivAssign",true),"%="=>("ModAssign",true),"%%="=>("FloatModAssign",true),":="=>("AssignInto",true),"&="=>("BitAndAssign",true),"&&="=>("AndAssign",true),"|="=>("BitOrAssign",true),"||="=>("OrAssign",true),"^="=>("BitXorAssign",true),"<<="=>("LShiftAssign",true),">>="=>("RShiftAssign",true),_=>return Ok(DebugSupport::Unissued("actual Original expression Debug binary product is not issued"))};out.push_str(if assignment{"AssignOp { op: "}else{"BinaryOp { op: "},self.a)?;out.push_str(op,self.a)?;out.push_str(", lhs: ",self.a)?;debug_step!(self.write_expression_debug_using(lhs,out,file));out.push_str(", rhs: ",self.a)?;debug_step!(self.write_expression_debug_using(rhs,out,file));out.push_str(" }",self.a)?;},
   dm_syntax::ExprKind::Conditional{condition,then_value,else_value}=>{out.push_str("TernaryOp { cond: ",self.a)?;debug_step!(self.write_expression_debug_using(condition,out,file));out.push_str(", if_: ",self.a)?;debug_step!(self.write_expression_debug_using(then_value,out,file));out.push_str(", else_: ",self.a)?;debug_step!(self.write_expression_debug_using(else_value,out,file));out.push_str(" }",self.a)?;},
   _=>{let mut term=expr;loop{self.check()?;match &term.kind{dm_syntax::ExprKind::Unary{op,value}if matches!(op.as_str(),"-"|"!"|"~"|"&"|"*"|"pre++"|"pre--"|"post++"|"post--")=>term=value,dm_syntax::ExprKind::Member{object,..}|dm_syntax::ExprKind::SafeMember{object,..}|dm_syntax::ExprKind::StaticMember{object,..}|dm_syntax::ExprKind::Index{object,..}|dm_syntax::ExprKind::SafeIndex{object,..}=>term=object,_=>break}}out.push_str("Base { term: Spanned { location: ",self.a)?;debug_step!(self.write_debug_term(term,out,file));out.push_str(" }, follow: [",self.a)?;let mut first=true;debug_step!(self.write_debug_unary_follows(expr,out,file,&mut first));out.push_str("] }",self.a)?;}
  }Ok(DebugSupport::Complete)
 }
 fn write_debug_unary_follows(&self,expr:&dm_syntax::Expr,out:&mut crate::macro_expansion::OriginalMacroText,file:&mut dyn FnMut(usize)->io::Result<u32>,first:&mut bool)->io::Result<DebugSupport>{self.check()?;let _frame=self.a.evaluation_frame().map_err(|error|self.a.take_operational_error().unwrap_or(error))?;if matches!(&expr.kind,dm_syntax::ExprKind::Member{..}|dm_syntax::ExprKind::SafeMember{..}|dm_syntax::ExprKind::StaticMember{..}|dm_syntax::ExprKind::Index{..}|dm_syntax::ExprKind::SafeIndex{..}){return self.write_debug_attached_follow(expr,out,file,first)}let dm_syntax::ExprKind::Unary{op,value}=&expr.kind else{return Ok(DebugSupport::Complete)};let(kind,punct,post)=match op.as_str(){"-"=>("Neg","-",false),"!"=>("Not","!",false),"~"=>("BitNot","~",false),"&"=>("Reference","&",false),"*"=>("Dereference","*",false),"pre++"=>("PreIncr","++",false),"pre--"=>("PreDecr","--",false),"post++"=>("PostIncr","++",true),"post--"=>("PostDecr","--",true),_=>return Ok(DebugSupport::Complete)};debug_step!(self.write_debug_unary_follows(value,out,file,first));let row=if post{let mut row=None;for candidate in self.rows.as_slice(){self.check()?;if candidate.span.end==expr.span.end{row=Some(candidate);break}}row.ok_or(io::ErrorKind::InvalidData)?}else{self.debug_row_at_start(expr.span.start)?};if !matches!(row.actual.value,OriginalTokenValue::Punct(actual)if actual==punct){return Err(io::ErrorKind::InvalidData.into())}if !*first{out.push_str(", ",self.a)?}*first=false;out.push_str("Spanned { location: ",self.a)?;self.debug_location(row,out,file)?;out.push_str(", elem: Unary(",self.a)?;out.push_str(kind,self.a)?;out.push_str(") }",self.a)?;Ok(DebugSupport::Complete)}
 fn write_debug_attached_follow(&self,expr:&dm_syntax::Expr,out:&mut crate::macro_expansion::OriginalMacroText,file:&mut dyn FnMut(usize)->io::Result<u32>,first:&mut bool)->io::Result<DebugSupport>{
  let(object,index,selector,access)=match &expr.kind{dm_syntax::ExprKind::Member{object,selector,via_colon}=>(object.as_ref(),None,Some(selector.as_str()),if *via_colon{"Colon"}else{"Dot"}),dm_syntax::ExprKind::SafeMember{object,selector,via_colon}=>(object.as_ref(),None,Some(selector.as_str()),if *via_colon{"SafeColon"}else{"SafeDot"}),dm_syntax::ExprKind::StaticMember{object,selector}=>(object.as_ref(),None,Some(selector.as_str()),"Static"),dm_syntax::ExprKind::Index{object,index}=>(object.as_ref(),Some(index.as_ref()),None,"Normal"),dm_syntax::ExprKind::SafeIndex{object,index}=>(object.as_ref(),Some(index.as_ref()),None,"Safe"),_=>return Err(io::ErrorKind::InvalidData.into())};
  debug_step!(self.write_debug_unary_follows(object,out,file,first));
  let mut actual=None;for row in self.rows.as_slice(){self.check()?;if row.span.start<object.span.end||row.span.start>=expr.span.end{continue}if matches!(row.actual.value,OriginalTokenValue::Punct(" "|"\t"|"\n")){continue}actual=Some(row);break}let row=actual.ok_or(io::ErrorKind::InvalidData)?;
  let expected=match access{"Dot"=>".","Colon"=>":","SafeDot"=>"?.","SafeColon"=>"?:","Static"=>"::","Normal"=>"[","Safe"=>"?[",_=>return Err(io::ErrorKind::InvalidData.into())};if !matches!(row.actual.value,OriginalTokenValue::Punct(op)if op==expected){return Ok(DebugSupport::Unissued("actual Original attached follow operator Debug product is not issued"))}
  if let Some(name)=selector{if !name.is_empty(){let mut bound=false;for candidate in self.rows.as_slice(){self.check()?;if candidate.span.end==expr.span.end&&matches!(&candidate.actual.value,OriginalTokenValue::Ident{spelling,..}if spelling.get()==name){bound=true;break}}if !bound{return Err(io::ErrorKind::InvalidData.into())}}}
  if !*first{out.push_str(", ",self.a)?;}*first=false;out.push_str("Spanned { location: ",self.a)?;self.debug_location(row,out,file)?;out.push_str(", elem: ",self.a)?;
  if let Some(index)=index{out.push_str("Index(",self.a)?;out.push_str(access,self.a)?;out.push_str(", ",self.a)?;debug_step!(self.write_expression_debug_using(index,out,file));out.push(')',self.a)?;}else{let name=selector.ok_or(io::ErrorKind::InvalidData)?;crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;if access=="Static"{write!(out,"StaticField({name:?})")}else{write!(out,"Field({access}, {name:?})")}})?;}out.push_str(" }",self.a)?;Ok(DebugSupport::Complete)
 }
 fn write_debug_term(&self,expr:&dm_syntax::Expr,out:&mut crate::macro_expansion::OriginalMacroText,file:&mut dyn FnMut(usize)->io::Result<u32>)->io::Result<DebugSupport>{self.check()?;let row=self.debug_row_at_start(expr.span.start)?;match &expr.kind{
  dm_syntax::ExprKind::Literal(literal)=>{if row.span!=expr.span{if literal.as_str()=="null"&&literal.original_value().is_none()&&self.debug_empty_parentheses(expr)?{self.debug_location(row,out,file)?;out.push_str(", elem: Null",self.a)?;return Ok(DebugSupport::Complete)}return Ok(DebugSupport::Unissued("actual non-scalar Original term Debug product is not issued"))}self.debug_location(row,out,file)?;out.push_str(", elem: ",self.a)?;let value=row.actual.value.map_text(|text|text.get());match (literal.original_value(),value){(Some(OriginalTokenValue::Int(wanted)),OriginalTokenValue::Int(actual))if wanted==actual=>crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Int({actual:?})")})?,(Some(OriginalTokenValue::Float(wanted)),OriginalTokenValue::Float(actual))if wanted.to_bits()==actual.to_bits()=>crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Float({actual:?})")})?,(Some(OriginalTokenValue::String(wanted)),OriginalTokenValue::String(actual))if wanted==actual=>crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"String({actual:?})")})?,(Some(OriginalTokenValue::Resource(wanted)),OriginalTokenValue::Resource(actual))if wanted==actual=>crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Resource({actual:?})")})?,(None,OriginalTokenValue::Ident{spelling:"null",..})if literal.as_str()=="null"=>out.push_str("Null",self.a)?,_=>return Ok(DebugSupport::Unissued("actual typed Original scalar Debug binding is not issued"))}},
  dm_syntax::ExprKind::Ident(name)=>{if row.span!=expr.span||!matches!(&row.actual.value,OriginalTokenValue::Ident{spelling,..}if spelling.get()==name){return Err(io::ErrorKind::InvalidData.into())}self.debug_location(row,out,file)?;out.push_str(", elem: ",self.a)?;if matches!(name.as_str(),"__TYPE__"|"__IMPLIED_TYPE__"){out.push_str(name,self.a)?;}else{crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Ident({name:?})")})?;}},
  dm_syntax::ExprKind::Call{callee,args}=>{let dm_syntax::ExprKind::Ident(name)=&callee.kind else{return Ok(DebugSupport::Unissued("actual Original dynamic/follow call term Debug product is not issued"))};if matches!(name.as_str(),"new"|"input"|"locate"|"pick"|"call"|"call_ext"|"__PROC__"|"__TYPE__"|"__IMPLIED_TYPE__"){return Ok(DebugSupport::Unissued("actual Original special call term Debug product is not issued"))}if row.span!=callee.span||!matches!(&row.actual.value,OriginalTokenValue::Ident{spelling,..}if spelling.get()==name){return Err(io::ErrorKind::InvalidData.into())}self.debug_location(row,out,file)?;out.push_str(", elem: ",self.a)?;if name=="list"{out.push_str("List([",self.a)?;}else{crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"Call({name:?}, [")})?;}for(index,arg)in args.iter().enumerate(){self.check()?;if index!=0{out.push_str(", ",self.a)?}debug_step!(self.write_expression_debug_using(arg,out,file));}out.push_str("])",self.a)?;},
  dm_syntax::ExprKind::TypePath(_)=>{self.debug_location(row,out,file)?;out.push_str(", elem: Prefab(Prefab { path: ",self.a)?;debug_step!(self.write_debug_prefab_path(expr,out));out.push_str(", vars: [] })",self.a)?;},
  dm_syntax::ExprKind::ObjectInitializer{object,fields}=>{if !matches!(&object.kind,dm_syntax::ExprKind::TypePath(_)){return Ok(DebugSupport::Unissued("actual Original initializer Debug lacks prefab target"))}self.debug_location(row,out,file)?;out.push_str(", elem: Prefab(Prefab { path: ",self.a)?;debug_step!(self.write_debug_prefab_path(object,out));out.push_str(", vars: [",self.a)?;for(index,(name,value))in fields.iter().enumerate(){self.check()?;if index!=0{out.push_str(", ",self.a)?;}crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"({name:?}, ")})?;debug_step!(self.write_expression_debug_using(value,out,file));out.push(')',self.a)?;}out.push_str("] })",self.a)?;},
  dm_syntax::ExprKind::Unary{op,value}if op=="::"=>{let dm_syntax::ExprKind::Ident(name)=&value.kind else{return Ok(DebugSupport::Unissued("actual Original global Debug name is not issued"))};if !matches!(row.actual.value,OriginalTokenValue::Punct("::")){return Err(io::ErrorKind::InvalidData.into())}let actual=self.debug_row_at_start(value.span.start)?;if actual.span!=value.span||!matches!(&actual.actual.value,OriginalTokenValue::Ident{spelling,..}if spelling.get()==name){return Err(io::ErrorKind::InvalidData.into())}self.debug_location(row,out,file)?;out.push_str(", elem: ",self.a)?;crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"GlobalIdent({name:?})")})?;},
  dm_syntax::ExprKind::Group(inner)=>{if !matches!(row.actual.value,OriginalTokenValue::Punct("(")){return Err(io::ErrorKind::InvalidData.into())}self.debug_location(row,out,file)?;out.push_str(", elem: Expr(",self.a)?;debug_step!(self.write_expression_debug_using(inner,out,file));out.push(')',self.a)?;},
  _=>return Ok(DebugSupport::Unissued("actual Original compound term/follow Debug product is not issued")),
 }Ok(DebugSupport::Complete)}
 fn debug_empty_parentheses(&self,expr:&dm_syntax::Expr)->io::Result<bool>{let mut seen=0;for row in self.rows.as_slice(){self.check()?;if row.span.start<expr.span.start||row.span.end>expr.span.end{continue}if matches!(row.actual.value,OriginalTokenValue::Punct(" "|"\t"|"\n")){continue}let expected=if seen==0{"("}else{")"};if seen>=2||!matches!(row.actual.value,OriginalTokenValue::Punct(actual)if actual==expected){return Ok(false)}seen+=1;}Ok(seen==2)}
 fn write_debug_prefab_path(&self,expr:&dm_syntax::Expr,out:&mut crate::macro_expansion::OriginalMacroText)->io::Result<DebugSupport>{out.push('[',self.a)?;let mut operator=None;let mut count=0;for row in self.rows.as_slice(){self.check()?;if row.span.start<expr.span.start||row.span.end>expr.span.end{continue}match &row.actual.value{OriginalTokenValue::Punct(" "|"\t"|"\n")=>(),OriginalTokenValue::Punct(op @ ("/"|"."|":"))=>operator=Some(match *op{"/"=>"Slash","."=>"Dot",_=>"Colon"}),OriginalTokenValue::Ident{spelling,..}=>{let Some(op)=operator.take()else{return Ok(DebugSupport::Unissued("actual Original prefab path Debug component operator is unissued"))};if count!=0{out.push_str(", ",self.a)?;}let name=spelling.get();crate::macro_expansion::original_format_using(out,self.a,|out|{use std::fmt::Write;write!(out,"({op}, {name:?})")})?;count+=1;},_=>return Ok(DebugSupport::Unissued("actual Original prefab path Debug token product is not issued"))}}if count==0||operator.is_some(){return Ok(DebugSupport::Unissued("actual Original root/trailing prefab Debug product is not issued"))}out.push(']',self.a)?;Ok(DebugSupport::Complete)}
 fn next_inner(&mut self)->io::Result<Option<Token>>{
  self.check()?;if !self.begun{return Err(io::ErrorKind::InvalidInput.into())}let Some(actual)=self.queue.pop()?else{return Ok(None)};
  let projection=project_native_token_using(&actual,self.provider,self.a,None)?;let start=self.next_offset.checked_add(usize::from(needs_separator(self.last,projection.adjacency))).ok_or(io::ErrorKind::OutOfMemory)?;let span=Span::new(start,start.checked_add(projection.spelling.as_str().len()).ok_or(io::ErrorKind::OutOfMemory)?);
  // SAME canonical adjacency as final output; unconditional gaps would
  // destroy actual /type path adjacency while preserving no extra identity.
  // Only actually pulled typed projected chunks enter this funded source.
  if self.source.as_str().len()!=self.next_offset{return Err(io::ErrorKind::InvalidData.into())}if start>self.next_offset{self.source.push(' ',self.a)?;}self.source.push_str(projection.spelling.as_str(),self.a)?;if self.source.as_str().len()!=span.end{return Err(io::ErrorKind::InvalidData.into())}
  self.next_offset=span.end;self.last=Some(projection.adjacency);
  // Keep the physical spelling inside its allocation-owning Text until every
  // fallible roster operation is complete. A failed push must not refund its
  // credit while a separately constructed Token still owns the String.
  let slot=self.rows.len();self.rows.push(Occurrence{actual,span,literal:projection.literal,credit:None},self.a)?;
  let(text,credit)=projection.spelling.into_parts();self.rows.as_mut_slice()[slot].credit=Some(credit);Ok(Some(Token{kind:projection.kind,span,text}))
 }
}
impl NativeExpressionTokenDemand for OriginalConditionTokens<'_,'_>{
 fn original_trivia_is_significant(&self)->bool{true}
 fn original_primitive_notice(&mut self,at:NativeExpressionTokenOccurrence,kind:dm_syntax::OriginalInputNoticeKind)->io::Result<()>{self.row(at)?;self.events.push(ParserEvent::Primitive{at,kind},self.a)}
 fn original_missing_member(&mut self,separator:NativeExpressionTokenOccurrence,following:Option<NativeExpressionTokenOccurrence>)->io::Result<bool>{let row=self.row(separator)?;if !matches!(row.actual.value,OriginalTokenValue::Punct("."|":"|"::"|"?."|"?:")){return Err(io::ErrorKind::InvalidData.into())}if let Some(next)=following{self.row(next)?;if next.ordinal()<=separator.ordinal(){return Err(io::ErrorKind::InvalidData.into())}}else if !self.queue.is_empty(){return Err(io::ErrorKind::InvalidData.into())}self.events.push(ParserEvent::MissingMember{separator,following},self.a)?;Ok(true)}

 fn requires_expression_end(&self)->bool{false}
 fn original_template_source(&self,span:Span)->io::Result<Option<&str>>{self.check()?;if self.source.as_str().len()!=self.next_offset||span.start>=span.end{return Err(io::ErrorKind::InvalidData.into())}let(mut begin,mut end)=(None,None);for row in self.rows.as_slice(){self.check()?;if row.span.start==span.start{begin=Some(row)}if row.span.end==span.end{end=Some(row)}}let(begin,end)=(begin.ok_or(io::ErrorKind::InvalidInput)?,end.ok_or(io::ErrorKind::InvalidInput)?);if !matches!(begin.literal.as_ref().map(OriginalLiteralData::value),Some(OriginalTokenValue::InterpBegin(_)))||!matches!(end.literal.as_ref().map(OriginalLiteralData::value),Some(OriginalTokenValue::InterpEnd(_))){return Err(io::ErrorKind::InvalidInput.into())}self.source.as_str().get(span.range()).map(Some).ok_or_else(||io::ErrorKind::InvalidData.into())}

 fn original_close_colon(&self,occurrence:NativeExpressionTokenOccurrence)->io::Result<Option<bool>>{let row=self.row(occurrence)?;Ok(matches!(row.actual.value,OriginalTokenValue::Punct(":" )).then_some(row.actual.punctuation_close))}

 fn begin_expression(&mut self)->io::Result<()>{self.check()?;if self.begun{self.failed.set(true);return Err(io::ErrorKind::InvalidInput.into())}self.begun=true;Ok(())}
 fn next_token(&mut self)->io::Result<Option<Token>>{let result=self.next_inner();if result.is_err(){self.failed.set(true)}result}
 fn take_token_credit(&mut self,occurrence:NativeExpressionTokenOccurrence)->io::Result<Option<SettingRootLease>>{self.row(occurrence)?;self.rows.as_mut_slice()[occurrence.ordinal()].credit.take().ok_or_else(||io::ErrorKind::InvalidInput.into()).map(Some)}
 fn original_value(&self,occurrence:NativeExpressionTokenOccurrence)->io::Result<Option<OriginalTokenValue<&str>>>{Ok(Some(self.row(occurrence)?.actual.value.map_text(|text|text.get())))}
 fn original_literal_data(&self,occurrence:NativeExpressionTokenOccurrence)->io::Result<Option<&OriginalLiteralData>>{Ok(self.row(occurrence)?.literal.as_ref())}
 fn requires_original_values(&self)->bool{true}
}

// The old condition parser takes output.drain(..): tokens it did not request
// after a syntax error still retire here, while each real buffer stays funded.
impl Drop for OriginalConditionTokens<'_,'_>{fn drop(&mut self){self.queue.discard_values();}}
